export function registerPdfFonts(doc: jsPDF): void {
  doc.addFileToVFS("DejaVuSans.ttf", DEJA_REGULAR_BASE64);
  doc.addFileToVFS("DejaVuSans-Bold.ttf", DEJA_BOLD_BASE64);
  doc.addFont("DejaVuSans.ttf", PDF_FONT_FAMILY, "normal");
  doc.addFont("DejaVuSans-Bold.ttf", PDF_FONT_FAMILY, "bold");
  doc.addFileToVFS("NotoSansArabic-Regular.ttf", AR_REGULAR_BASE64);
  doc.addFileToVFS("NotoSansArabic-Bold.ttf", AR_BOLD_BASE64);
  doc.addFont("NotoSansArabic-Regular.ttf", PDF_ARABIC_FONT_FAMILY, "normal");
  doc.addFont("NotoSansArabic-Bold.ttf", PDF_ARABIC_FONT_FAMILY, "bold");
  doc.addFileToVFS("NotoKufiArabic-Regular.ttf", KUFI_REGULAR_BASE64);
  doc.addFileToVFS("NotoKufiArabic-Bold.ttf", KUFI_BOLD_BASE64);
  doc.addFont("NotoKufiArabic-Regular.ttf", PDF_LEGACY_FONT_FAMILY, "normal");
  doc.addFont("NotoKufiArabic-Bold.ttf", PDF_LEGACY_FONT_FAMILY, "bold");
}
